// server.ts  (requires Node 18+ and an API key)
// npm install express @anthropic-ai/sdk
// npm install -D typescript tsx @types/express @types/node
import express, { Request, Response } from "express";
import Anthropic from "@anthropic-ai/sdk";

const MODEL = process.env.MODEL;           // copy an id from the provider's models page
if (!MODEL) throw new Error("Set the MODEL environment variable");

const client = new Anthropic();            // reads ANTHROPIC_API_KEY from the environment
const app = express();
app.use(express.json({ limit: "100kb" }));

interface AskBody {
  question: string;
}

app.post("/api/ask", async (req: Request<{}, {}, AskBody>, res: Response) => {
  const question = req.body?.question;
  if (typeof question !== "string" || question.length === 0 || question.length > 2000) {
    return res.status(400).json({ error: "question must be 1 to 2000 characters" });
  }
  try {
    const msg = await client.messages.create({
      model: MODEL,
      max_tokens: 1024,
      system: "You answer questions about Larkwhistle Freight's shipping policy. Be brief.",
      messages: [{ role: "user", content: question }],
    });
    const answer = msg.content
      .map((block) => (block.type === "text" ? block.text : ""))
      .join("");
    return res.json({ answer, usage: msg.usage });
  } catch (err) {
    if (err instanceof Anthropic.APIError) {
      console.error("LLM error", err.status, err.message);   // log details on the server
      return res.status(502).json({ error: "upstream model error" });  // generic to the client
    }
    throw err;
  }
});

app.listen(3000, () => console.log("listening on http://localhost:3000"));
